import sys
sys.setrecursionlimit(200000)
def solve(n, m, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    timer = 0
    tin = [-1] * n
    low = [-1] * n
    bridges = []

    def dfs(v, p=-1):
        nonlocal timer
        tin[v] = low[v] = timer
        timer += 1
        for to in adj[v]:
            if to == p: continue
            if tin[to] != -1: low[v] = min(low[v], tin[to])
            else:
                dfs(to, v)
                low[v] = min(low[v], low[to])
                if low[to] > tin[v]: bridges.append((min(v, to), max(v, to)))

    for i in range(n):
        if tin[i] == -1: dfs(i)

    bridges.sort()
    out = [str(len(bridges))]
    for u, v in bridges:
        out.append(f"{u} {v}")
    return "\n".join(out)

if __name__ == '__main__':
    input_data = sys.stdin.read().split()
    if not input_data: exit()
    n, m = int(input_data[0]), int(input_data[1])
    edges = []
    idx = 2
    for _ in range(m):
        edges.append([int(input_data[idx]), int(input_data[idx+1])])
        idx += 2
    print(solve(n, m, edges))

